const input = $input.first().json;
if (!input || !input.config || !input.batch || !input.pair) {
  throw new Error('Expected config, batch and pair objects from the batch controller.');
}
const config = input.config;
const batch = input.batch;
const pair = input.pair;
if (!/^https:\/\/[^/]+\.supabase\.co$/i.test(config.supabase_url || '')) {
  throw new Error('Set a valid Supabase project URL in the batch controller.');
}
const permittedModels = new Set(['gpt-5.4-mini', 'gpt-5.4-nano']);
for (const field of ['question_model', 'page_map_model', 'mark_scheme_model', 'metadata_model', 'repair_model']) {
  if (!permittedModels.has(config[field])) {
    throw new Error('Unsupported guarded model in config.' + field + ': ' + config[field]);
  }
}
const reservations = config.stage_reservations_usd || {};
for (const [stage, amount] of Object.entries(reservations)) {
  if (!(Number(amount) > 0) || Number(amount) > 0.25) {
    throw new Error('Each stage reservation must be greater than $0 and no more than $0.25: ' + stage);
  }
}
if (!batch.id || !batch.batch_key) throw new Error('The Supabase batch row is missing.');
if (!Array.isArray(pair.documents) || pair.documents.length !== 2) {
  throw new Error('Each paper pair must contain exactly a question paper and mark scheme.');
}
const types = new Set(pair.documents.map((document) => document.document_type));
if (!types.has('question_paper') || !types.has('mark_scheme')) {
  throw new Error('The pair must contain one question paper and one mark scheme.');
}
for (const document of pair.documents) {
  if (!/^https:\/\//i.test(document.source_url || '')) {
    throw new Error('Every document needs an HTTPS source URL.');
  }
}
const paperType = String(pair.paper_variant || '').charAt(0);
const expectedTotalMarks = ['1', '3'].includes(paperType) ? 75 : 50;
const sourceKey = [
  pair.qualification,
  pair.syllabus_code,
  pair.year,
  pair.exam_session,
  pair.paper_variant,
].join(':');
const idempotencyKey = ['budget-v2', batch.batch_key, sourceKey].join(':');
return [{
  json: {
    config,
    batch,
    pair,
    batch_position: input.batch_position,
    batch_size: input.batch_size,
    source_key: sourceKey,
    idempotency_key: idempotencyKey,
    expected_total_marks: expectedTotalMarks,
  },
}];

const response = $input.first().json;
const rows = Array.isArray(response) ? response : (response?.id ? [response] : []);
const state = $('Validate Paper Input').first().json;
if (!rows.length) return [{ json: { ...state, skip_existing: false } }];
const run = rows[0];
const finishedStatuses = [
  'awaiting_review',
  'approved',
  'published',
  'search_pending',
  'complete',
];
if (finishedStatuses.includes(run.status)) {
  return [{
    json: {
      ...state,
      skip_existing: true,
      existing_run: run,
    },
  }];
}
if (run.status === 'processing') {
  throw new Error(
    'This paper already has a processing run. Inspect ingestion run ' + run.id +
    ' before retrying to avoid duplicate API work.'
  );
}
return [{ json: { ...state, skip_existing: false, retry_run: run } }];

const state = $input.first().json;
return [{
  json: {
    success: true,
    skipped_existing: true,
    message: 'This paper was already staged or published, so no OCR or OpenAI call was made.',
    ingestion_run_id: state.existing_run.id,
    paper_id: state.existing_run.paper_id,
    batch_id: state.batch.id,
    batch_position: state.batch_position,
    batch_size: state.batch_size,
    config: state.config,
    actual_cost_usd: 0,
    ready_for_approval: state.existing_run.validation_report?.passed === true,
  },
}];

const state = $input.first().json;
return [{
  json: {
    ...state,
    paper_row: {
      qualification: state.pair.qualification,
      syllabus_code: state.pair.syllabus_code,
      subject: state.pair.subject,
      year: state.pair.year,
      exam_session: state.pair.exam_session,
      paper_variant: state.pair.paper_variant,
      status: 'staging',
    },
  },
}];

const response = $input.first().json;
const paper = Array.isArray(response) ? response[0] : response;
const state = $('Prepare Paper Upsert').first().json;
if (!paper?.id) throw new Error('Supabase did not return the paper row.');
return [{
  json: {
    ...state,
    paper_id: paper.id,
    run_body: {
      paper_id: paper.id,
      idempotency_key: state.idempotency_key,
      mode: 'production',
      status: 'processing',
      review_status: 'pending',
      source_key: state.source_key,
      ocr_model: state.config.ocr_model,
      extraction_model: state.config.question_model,
      verifier_model: null,
      attempt_count: Number(state.retry_run?.attempt_count || 0) + 1,
      source_summary: {
        batch_id: state.batch.id,
        batch_key: state.batch.batch_key,
        batch_position: state.batch_position,
        documents: state.pair.documents,
      },
      extraction_summary: {},
      verifier_report: {},
      validation_report: {},
      started_at: new Date().toISOString(),
      finished_at: null,
    },
  },
}];

const response = $input.first().json;
const run = Array.isArray(response) ? response[0] : response;
const state = $('Prepare Ingestion Run').first().json;
if (!run?.id) throw new Error('Supabase did not return the ingestion run.');
return state.pair.documents.map((document, index) => ({
  json: {
    config: state.config,
    batch: state.batch,
    pair: state.pair,
    batch_position: state.batch_position,
    batch_size: state.batch_size,
    paper_id: state.paper_id,
    ingestion_run_id: run.id,
    source_key: state.source_key,
    idempotency_key: state.idempotency_key,
    expected_total_marks: state.expected_total_marks,
    document,
    mistral_request: {
      model: state.config.ocr_model,
      document: {
        type: 'document_url',
        document_url: document.source_url,
      },
      bbox_annotation_format: {
        type: 'json_schema',
        json_schema: {
          name: 'shamo_instructional_asset',
          strict: true,
          schema: {"type":"object","properties":{"asset_type":{"type":"string","enum":["graph","geometry_diagram","mechanics_diagram","table","number_line","coordinate_grid","decorative_or_irrelevant","other_instructional"]},"description":{"type":"string"},"required_to_solve":{"type":"boolean"},"likely_question_number":{"anyOf":[{"type":"integer"},{"type":"null"}]},"part_path":{"type":"array","maxItems":4,"items":{"type":"string"}},"mathematical_details":{"type":"object","properties":{"visible_labels":{"type":"array","items":{"type":"string"}},"equations":{"type":"array","items":{"type":"string"}},"coordinates":{"type":"array","items":{"type":"string"}},"measurements":{"type":"array","items":{"type":"string"}},"relationships":{"type":"array","items":{"type":"string"}}},"required":["visible_labels","equations","coordinates","measurements","relationships"],"additionalProperties":false}},"required":["asset_type","description","required_to_solve","likely_question_number","part_path","mathematical_details"],"additionalProperties":false},
        },
      },
      include_image_base64: true,
      confidence_scores_granularity: 'page',
    },
  },
  pairedItem: { item: index },
}));

const responses = $input.all();
const sources = $('Expand Paper Documents').all();
if (responses.length !== 2 || sources.length !== 2) {
  throw new Error('OCR must return exactly two document responses.');
}
return responses.map((item, index) => {
  const source = sources[index].json;
  const ocr = item.json;
  if (!Array.isArray(ocr.pages) || !ocr.pages.length) {
    throw new Error('Mistral OCR returned no pages for ' + source.document.document_type + '.');
  }
  return {
    json: {
      ...source,
      ocr_model_returned: ocr.model || source.config.ocr_model,
      ocr_usage: ocr.usage_info || {},
      pages: ocr.pages,
    },
  };
});

const documents = $input.all().map((item) => item.json);
if (documents.length !== 2) throw new Error('Expected exactly two OCR documents.');
const first = documents[0];
const pageRows = [];
const compactDocuments = [];
for (const document of documents) {
  const compactPages = [];
  for (const page of document.pages) {
    const pageNumber = Number(page.index) + 1;
    pageRows.push({
      ingestion_run_id: document.ingestion_run_id,
      document_type: document.document.document_type,
      page_number: pageNumber,
      raw_markdown: page.markdown || '',
      ocr_confidence: page.confidence ?? page.confidence_score ?? null,
    });
    compactPages.push({
      page_number: pageNumber,
      markdown: page.markdown || '',
      images: (page.images || []).map((image, imageIndex) => ({
        source_image_index: imageIndex,
        id: image.id || null,
        top_left_x: image.top_left_x ?? null,
        top_left_y: image.top_left_y ?? null,
        bottom_right_x: image.bottom_right_x ?? null,
        bottom_right_y: image.bottom_right_y ?? null,
        image_annotation: image.image_annotation || null,
      })),
    });
  }
  compactDocuments.push({
    document_type: document.document.document_type,
    source_url: document.document.source_url,
    page_count: document.pages.length,
    ocr_model: document.ocr_model_returned,
    pages: compactPages,
  });
}
return [{
  json: {
    config: first.config,
    batch: first.batch,
    pair: first.pair,
    batch_position: first.batch_position,
    batch_size: first.batch_size,
    paper_id: first.paper_id,
    ingestion_run_id: first.ingestion_run_id,
    source_key: first.source_key,
    idempotency_key: first.idempotency_key,
    expected_total_marks: first.expected_total_marks,
    ocr_documents: documents,
    compact_documents: compactDocuments,
    known_documents: compactDocuments.map((document) => ({
      document_type: document.document_type,
      source_url: document.source_url,
      source_url_hash: null,
      page_count: document.page_count,
      ocr_model: document.ocr_model,
    })),
    ocr_page_rows: pageRows,
  },
}];

const state = $('Build OCR State').first().json;
const openaiIdempotencyKey = state.idempotency_key + ':question_paper_extraction';
return [{
  json: {
    ...state,
    openai_idempotency_key: openaiIdempotencyKey,
    reserve_body: {
      requested_batch_id: state.batch.id,
      requested_ingestion_run_id: state.ingestion_run_id,
      requested_idempotency_key: openaiIdempotencyKey,
      requested_provider: 'openai',
      requested_model: state.config.question_model,
      requested_operation: 'question_paper_extraction',
      requested_reserved_usd: state.config.stage_reservations_usd.question_paper,
    },
  },
}];

const reservationResponse = $input.first().json;
const reservation = Array.isArray(reservationResponse) ? reservationResponse[0] : reservationResponse;
const state = $('Prepare Question Paper Reservation').first().json;
if (!reservation?.cost_event_id) throw new Error('Question-paper budget reservation was not returned.');
const questionPaper = state.compact_documents.find((document) => document.document_type === 'question_paper');
if (!questionPaper) throw new Error('Question-paper OCR document is missing.');
const prompt = [
  'Extract only the question paper from this official Cambridge Mathematics paper.',
  'The paper identity is supplied in the request. Its expected total is ' + state.expected_total_marks + ' marks.',
  'Use the PDF as the visual source of truth and OCR JSON as a page-indexed aid.',
  'Return every main question in numerical order and make question totals add exactly to the expected paper total.',
  'Transcribe every mathematical sign, exponent, radical, limit, coordinate and inequality exactly.',
  'A main question number is an integer. Never put labels such as (a) in question_number.',
  'Create a part only when a label such as (a), (b), (i) or (ii) is visibly printed.',
  'For nested parts use paths such as ["a","i"]. Never include the main question number in label_path.',
  'For an unparted question use parts=[] and put the complete question in stem_markdown.',
  'Do not duplicate an instruction between stem_markdown and a part prompt.',
  'When a parent part has child parts, keep its shared prompt but set its marks to null unless a separate mark value is visibly printed for the parent.',
  'Use 1-based PDF page numbers. Ignore answer lines, barcodes, footers and margin instructions.',
  'Include only diagrams, graphs and tables needed to understand or solve a question.',
  'Every asset must match an OCR image using its exact page number and zero-based source_image_index.',
  'Do not extract mark-scheme content or topic metadata in this call.',
].join('\n');
return [{
  json: {
    ...state,
    cost_event_id: reservation.cost_event_id,
    question_paper_request: {
      model: state.config.question_model,
      reasoning: { effort: 'medium' },
      store: false,
      max_output_tokens: 22000,
      input: [
        { role: 'system', content: prompt },
        {
          role: 'user',
          content: [
            {
              type: 'input_text',
              text: JSON.stringify({
                paper: {
                  qualification: state.pair.qualification,
                  syllabus_code: state.pair.syllabus_code,
                  subject: state.pair.subject,
                  year: state.pair.year,
                  exam_session: state.pair.exam_session,
                  paper_variant: state.pair.paper_variant,
                  expected_total_marks: state.expected_total_marks,
                },
                question_paper_ocr: questionPaper,
              }),
            },
            { type: 'input_file', file_url: questionPaper.source_url },
          ],
        },
      ],
      text: {
        format: {
          type: 'json_schema',
          name: 'shamo_v2_question_paper',
          strict: true,
          schema: {"type":"object","properties":{"questions":{"type":"array","minItems":1,"items":{"type":"object","properties":{"question_number":{"type":"integer","minimum":1},"stem_markdown":{"type":"string"},"total_marks":{"type":"integer","minimum":0},"source_page_numbers":{"type":"array","minItems":1,"items":{"type":"integer","minimum":1}},"parts":{"type":"array","items":{"type":"object","properties":{"label_path":{"type":"array","minItems":1,"maxItems":4,"items":{"type":"string","pattern":"^[A-Za-z0-9]+$"}},"prompt_markdown":{"type":"string"},"marks":{"anyOf":[{"type":"integer"},{"type":"null"}]},"source_page_numbers":{"type":"array","minItems":1,"items":{"type":"integer","minimum":1}},"sort_order":{"type":"integer","minimum":0}},"required":["label_path","prompt_markdown","marks","source_page_numbers","sort_order"],"additionalProperties":false}},"assets":{"type":"array","items":{"type":"object","properties":{"part_path":{"type":"array","maxItems":4,"items":{"type":"string","pattern":"^[A-Za-z0-9]+$"}},"document_type":{"type":"string","enum":["question_paper","mark_scheme"]},"source_page_number":{"type":"integer","minimum":1},"source_image_index":{"type":"integer","minimum":0},"asset_type":{"type":"string","enum":["graph","geometry_diagram","mechanics_diagram","table","number_line","coordinate_grid","other_instructional"]},"bounding_box":{"anyOf":[{"type":"object","properties":{"top_left_x":{"type":"number"},"top_left_y":{"type":"number"},"bottom_right_x":{"type":"number"},"bottom_right_y":{"type":"number"}},"required":["top_left_x","top_left_y","bottom_right_x","bottom_right_y"],"additionalProperties":false},{"type":"null"}]},"description":{"type":"string"},"mathematical_details":{"type":"object","properties":{"visible_labels":{"type":"array","items":{"type":"string"}},"equations":{"type":"array","items":{"type":"string"}},"coordinates":{"type":"array","items":{"type":"string"}},"measurements":{"type":"array","items":{"type":"string"}},"relationships":{"type":"array","items":{"type":"string"}}},"required":["visible_labels","equations","coordinates","measurements","relationships"],"additionalProperties":false},"required_to_solve":{"type":"boolean"}},"required":["part_path","document_type","source_page_number","source_image_index","asset_type","bounding_box","description","mathematical_details","required_to_solve"],"additionalProperties":false}}},"required":["question_number","stem_markdown","total_marks","source_page_numbers","parts","assets"],"additionalProperties":false}}},"required":["questions"],"additionalProperties":false},
        },
      },
    },
  },
}];

const response = $input.first().json;
const state = $('Build Question Paper Request').first().json;
if (response.status === 'incomplete') {
  throw new Error('Question-paper extraction was incomplete: ' + JSON.stringify(response.incomplete_details || {}));
}
const message = (response.output || []).find((entry) => entry.type === 'message');
if (!message) throw new Error('Question-paper extraction returned no message output.');
const refusal = (message.content || []).find((entry) => entry.type === 'refusal');
if (refusal) throw new Error('Question-paper extraction refused: ' + (refusal.refusal || 'unknown refusal'));
const outputText = (message.content || []).find((entry) => entry.type === 'output_text');
if (!outputText?.text) throw new Error('Question-paper extraction returned no structured text.');
const extracted = JSON.parse(outputText.text);
if (!Array.isArray(extracted.questions) || !extracted.questions.length) {
  throw new Error('Question-paper extraction has no questions.');
}
const model = state.config.question_model;

const usage = response.usage || {};
const inputTokens = Number(usage.input_tokens || 0);
const cachedInputTokens = Number(usage.input_tokens_details?.cached_tokens || 0);
const outputTokens = Number(usage.output_tokens || 0);
const prices = state.config.openai_prices_per_million[model];
if (!prices) throw new Error('No price configuration exists for ' + model + '.');
const actualCostUsd =
  Math.max(0, inputTokens - cachedInputTokens) * Number(prices.input) / 1000000 +
  cachedInputTokens * Number(prices.cached_input) / 1000000 +
  outputTokens * Number(prices.output) / 1000000;
return [{
  json: {
    ...state,
    question_paper_questions: extracted.questions,
    extraction_response_ids: [response.id || null],
    api_events: [{
      operation: 'question_paper_extraction',
      model,
      input_tokens: inputTokens,
      cached_input_tokens: cachedInputTokens,
      output_tokens: outputTokens,
      actual_cost_usd: Number(actualCostUsd.toFixed(8)),
    }],
    finalize_cost_body: {
      requested_cost_event_id: state.cost_event_id,
      requested_input_tokens: inputTokens,
      requested_cached_input_tokens: cachedInputTokens,
      requested_output_tokens: outputTokens,
      requested_actual_usd: Number(actualCostUsd.toFixed(8)),
      requested_provider_request_id: response.id || null,
    },
  },
}];

const state = $('Restore Question Paper State').first().json;
const openaiIdempotencyKey = state.idempotency_key + ':mark_scheme_page_map';
return [{
  json: {
    ...state,
    openai_idempotency_key: openaiIdempotencyKey,
    reserve_body: {
      requested_batch_id: state.batch.id,
      requested_ingestion_run_id: state.ingestion_run_id,
      requested_idempotency_key: openaiIdempotencyKey,
      requested_provider: 'openai',
      requested_model: state.config.page_map_model,
      requested_operation: 'mark_scheme_page_map',
      requested_reserved_usd: state.config.stage_reservations_usd.page_map,
    },
  },
}];

const reservationResponse = $input.first().json;
const reservation = Array.isArray(reservationResponse) ? reservationResponse[0] : reservationResponse;
const state = $('Prepare Page Map Reservation').first().json;
if (!reservation?.cost_event_id) throw new Error('Page-map budget reservation was not returned.');
const markScheme = state.compact_documents.find((document) => document.document_type === 'mark_scheme');
if (!markScheme) throw new Error('Mark-scheme OCR document is missing.');
const prompt = [
  'Map the official Cambridge mark scheme by main question number.',
  'This is routing only: do not transcribe answers and do not solve anything.',
  'For every visible main question, return every 1-based PDF page on which its mark-scheme table continues.',
  'A page can belong to two questions when one ends and the next begins on that page.',
  'Do not confuse part labels, mark values, page numbers or totals with main question numbers.',
  'Use the printed paper total when visible. Otherwise return source_total_marks=null.',
].join('\n');
return [{
  json: {
    ...state,
    cost_event_id: reservation.cost_event_id,
    page_map_request: {
      model: state.config.page_map_model,
      reasoning: { effort: 'low' },
      store: false,
      max_output_tokens: 3000,
      input: [
        { role: 'system', content: prompt },
        {
          role: 'user',
          content: [{
            type: 'input_text',
            text: JSON.stringify({
              paper_variant: state.pair.paper_variant,
              expected_question_numbers: state.question_paper_questions.map((question) => question.question_number),
              mark_scheme_ocr: markScheme,
            }),
          }],
        },
      ],
      text: {
        format: {
          type: 'json_schema',
          name: 'shamo_v2_mark_scheme_page_map',
          strict: true,
          schema: {"type":"object","properties":{"source_question_count":{"anyOf":[{"type":"integer"},{"type":"null"}]},"source_total_marks":{"anyOf":[{"type":"integer"},{"type":"null"}]},"question_pages":{"type":"array","minItems":1,"items":{"type":"object","properties":{"question_number":{"type":"integer","minimum":1},"page_numbers":{"type":"array","minItems":1,"items":{"type":"integer","minimum":1}}},"required":["question_number","page_numbers"],"additionalProperties":false}}},"required":["source_question_count","source_total_marks","question_pages"],"additionalProperties":false},
        },
      },
    },
  },
}];

const response = $input.first().json;
const state = $('Build Page Map Request').first().json;
if (response.status === 'incomplete') throw new Error('Page-map extraction was incomplete.');
const message = (response.output || []).find((entry) => entry.type === 'message');
const outputText = (message?.content || []).find((entry) => entry.type === 'output_text');
if (!outputText?.text) throw new Error('Page-map extraction returned no structured text.');
const extracted = JSON.parse(outputText.text);
const pageMap = {};
for (const entry of extracted.question_pages || []) {
  const number = Number(entry.question_number);
  const pages = [...new Set((entry.page_numbers || []).map(Number))].sort((a, b) => a - b);
  if (pageMap[number]) throw new Error('Page map contains duplicate question ' + number + '.');
  pageMap[number] = pages;
}
const model = state.config.page_map_model;

const usage = response.usage || {};
const inputTokens = Number(usage.input_tokens || 0);
const cachedInputTokens = Number(usage.input_tokens_details?.cached_tokens || 0);
const outputTokens = Number(usage.output_tokens || 0);
const prices = state.config.openai_prices_per_million[model];
if (!prices) throw new Error('No price configuration exists for ' + model + '.');
const actualCostUsd =
  Math.max(0, inputTokens - cachedInputTokens) * Number(prices.input) / 1000000 +
  cachedInputTokens * Number(prices.cached_input) / 1000000 +
  outputTokens * Number(prices.output) / 1000000;
return [{
  json: {
    ...state,
    mark_scheme_page_map: pageMap,
    paper_summary: {
      question_count_from_source: Number.isInteger(extracted.source_question_count)
        ? extracted.source_question_count
        : null,
      total_marks_from_source: state.expected_total_marks,
      mark_scheme_total_marks_reported: Number.isInteger(extracted.source_total_marks)
        ? extracted.source_total_marks
        : null,
    },
    extraction_response_ids: [...(state.extraction_response_ids || []), response.id || null],
    api_events: [...(state.api_events || []), {
      operation: 'mark_scheme_page_map',
      model,
      input_tokens: inputTokens,
      cached_input_tokens: cachedInputTokens,
      output_tokens: outputTokens,
      actual_cost_usd: Number(actualCostUsd.toFixed(8)),
    }],
    finalize_cost_body: {
      requested_cost_event_id: state.cost_event_id,
      requested_input_tokens: inputTokens,
      requested_cached_input_tokens: cachedInputTokens,
      requested_output_tokens: outputTokens,
      requested_actual_usd: Number(actualCostUsd.toFixed(8)),
      requested_provider_request_id: response.id || null,
    },
  },
}];

const state = $('Restore Page Map State').first().json;
const openaiIdempotencyKey = state.idempotency_key + ':mark_scheme_question_extraction';
return [{
  json: {
    ...state,
    openai_idempotency_key: openaiIdempotencyKey,
    reserve_body: {
      requested_batch_id: state.batch.id,
      requested_ingestion_run_id: state.ingestion_run_id,
      requested_idempotency_key: openaiIdempotencyKey,
      requested_provider: 'openai',
      requested_model: state.config.mark_scheme_model,
      requested_operation: 'mark_scheme_question_extraction',
      requested_reserved_usd: state.config.stage_reservations_usd.mark_scheme,
    },
  },
}];

const reservationResponse = $input.first().json;
const reservation = Array.isArray(reservationResponse) ? reservationResponse[0] : reservationResponse;
const state = $('Prepare Mark Scheme Reservation').first().json;
if (!reservation?.cost_event_id) throw new Error('Mark-scheme budget reservation was not returned.');
const markScheme = state.compact_documents.find((document) => document.document_type === 'mark_scheme');
if (!markScheme) throw new Error('Mark-scheme OCR document is missing.');
const pageByNumber = new Map(markScheme.pages.map((page) => [Number(page.page_number), page]));
